// Offline fixture: actual production Queue/Drain/Append are generated by the runner.
// Only file/PID/time surroundings are isolated. Never loads YMCC or a device SDK.
#define NOMINMAX
#include <algorithm>
#include <array>
#include <atomic>
#include <chrono>
#include <cstdlib>
#include <deque>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <iterator>
